p = 61
N_R = {k: 0 for k in range(p)}

# Iterate over a and b in the range [1, 61]
for a in range(1, p + 1):
    a_sq = (a * a) % p
    for b in range(1, p + 1):
        b_sq = (b * b) % p
        k = (a_sq + b_sq) % p
        N_R[k] += 1

print("N_R counts for k=0 to 60:")
for k in range(p):
    print(f"k={k}: {N_R[k]}")

M = 61
count = 0
for a in range(M):
    for b in range(M):
        for c in range(M):
            for d in range(M):
                # Calculate a^2 + b^2 + c^3 - d^3 mod 61
                val = (a*a + b*b + c**3 - d**3) % M
                if val == 0:
                    count += 1

print(f"Calculated number of quadruples: {count}")
